effect.frag.content:
uniform float u_amount;
vec4 sourceAt(vec2 uv) {
  if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) return vec4(0.0);
  return texture(u_source, uv);
}
vec4 over(vec4 front, vec4 back) { return front + back * (1.0 - front.a); }
void main() {
  vec4 color = sourceAt(v_uv) * 0.45;
  for (int i = 0; i < 5; i++) {
    float index = float(i), visible = step(index / 7.0, u_progress);
    vec2 center = vec2(0.34, 0.62) + vec2(0.07, -0.07) * index;
    vec2 p = (v_uv - center) / (0.4 + u_amount * 0.15) + 0.5;
    if (visible > 0.0 && all(greaterThanEqual(p, vec2(0.0))) && all(lessThanEqual(p, vec2(1.0)))) {
      vec4 c = sourceAt(p);
      bool frame = p.x < 0.035 || p.x > 0.965 || p.y < 0.035 || p.y > 0.8;
      if (frame) c = vec4(0.15, 0.32, 0.42, 1.0);
      if (p.x > 0.88 && p.y > 0.85) c = vec4(0.9, 0.35, 0.2, 1.0);
      color = over(c, color);
    }
  }
  fragColor = color;
}
